using System.Reflection;
using System.Runtime.CompilerServices;
using System.Text.Json;
using CombatSolver.Engine.Common;
using HarmonyLib;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Models;

namespace CombatSolver;

internal static class ListenerProducerProbe
{
    private static readonly Type State = typeof(SimulatedCombatState);
    private static readonly Type Joined = State.GetNestedType("ConcatenatedListenerView",BindingFlags.NonPublic)!;
    private static FieldInfo Field(string name)=>State.GetField(name,BindingFlags.Instance|BindingFlags.NonPublic)!;
    private static readonly FieldInfo Base=Field("_baseHookListeners"), Hook=Field("_mirroredHookLayout"), Run=Field("_mirroredRunHookLayout");
    private static readonly FieldInfo Active=Field("_activeHookListeners"), WholeRun=Field("_effectiveRunHookListeners");
    private static readonly FieldInfo HookResult=Field("_mirroredHookListeners"), RunResult=Field("_mirroredRunHookListeners");
    private readonly record struct Segment(MirroredHookListenerLayout? Layout,int Offset,int Length);
    private sealed class Segments { internal readonly object Gate=new(); internal Segment Hook,Run; }
    private static readonly ConditionalWeakTable<SimulatedCombatState,Segments> Recorded=new();
    private static long _cached,_rebuilt,_unknown,_created,_inherited;
    private static readonly long[] Found=new long[2],Missing=new long[2],Match=new long[2],Slots=new long[2],MatchSlots=new long[2],Compared=new long[2];
    private static Segments Get(SimulatedCombatState state)=>Recorded.GetValue(state,static _=>{Interlocked.Increment(ref _created);return new();});
    [ModuleInitializer]
    internal static void Install()
    {
        string? path=Environment.GetEnvironmentVariable("LISTENER_PRODUCER_PROBE_OUTPUT");if(path is null)return;
        Harmony h=new("CombatSolver.Diagnostics.ListenerProducerV2");
        MethodInfo Method(string name)=>State.GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic)!;
        MethodInfo Helper(string name)=>typeof(ListenerProducerProbe).GetMethod(name,BindingFlags.Static|BindingFlags.NonPublic)!;
        h.Patch(Method("GetBaseHookListeners"),prefix:new HarmonyMethod(Helper(nameof(BeforeBase))),postfix:new HarmonyMethod(Helper(nameof(AfterBase))));
        h.Patch(Method("GetMirroredHookListeners"),prefix:new HarmonyMethod(Helper(nameof(BeforeFiltered))),postfix:new HarmonyMethod(Helper(nameof(AfterFiltered))));
        h.Patch(Method(typeof(ICombatPredictionForkableState).FullName+".Fork"),postfix:new HarmonyMethod(Helper(nameof(AfterFork))));
        AppDomain.CurrentDomain.ProcessExit+=(_,_)=>File.WriteAllText(path,JsonSerializer.Serialize(new{
            scope="Diagnostic only; weak state ownership of two model-free type segments, inherited on Fork. Counts do not prove speed or unique CPU savings.",
            cachedCalls=_cached,rebuiltCalls=_rebuilt,unknownCollections=_unknown,createdStateMetadata=_created,inheritedMetadata=_inherited,
            columns=new[]{"combat","run"},found=Found,missing=Missing,matchingSuffixes=Match,candidateSuffixSlots=Slots,
            matchingSuffixSlots=MatchSlots,comparedSlotsBeforeMismatch=Compared
        },new JsonSerializerOptions{WriteIndented=true}));
    }
    private static void BeforeBase(SimulatedCombatState __instance,out object? __state)=>__state=Base.GetValue(__instance);
    private static void BeforeFiltered(SimulatedCombatState __instance,bool run,out object? __state)=>__state=(run?RunResult:HookResult).GetValue(__instance);
    private static bool Frozen(IReadOnlyList<AbstractModel> source)
        =>source.GetType()==typeof(AbstractModel[])||source.GetType()==typeof(List<AbstractModel>)
            ||source.GetType()==Joined&&source is ISegmentedModelList view&&Frozen(view.Prefix)&&Frozen(view.Suffix);
    private static bool EndsWith(IReadOnlyList<AbstractModel> complete,IReadOnlyList<AbstractModel> suffix)
        =>ReferenceEquals(complete,suffix)||complete.GetType()==Joined&&complete is ISegmentedModelList view&&EndsWith(view.Suffix,suffix);
    private static void AfterBase(SimulatedCombatState __instance,IReadOnlyList<AbstractModel> __result,object? __state)
    {
        if(ReferenceEquals(__result,__state)){Interlocked.Increment(ref _cached);return;}
        Interlocked.Increment(ref _rebuilt);
        if(__result.GetType()!=Joined||__result is not ISegmentedModelList view||!Frozen(view.Suffix))
        {Interlocked.Increment(ref _unknown);return;}
        Recorded.TryGetValue(__instance,out var record);var suffix=view.Suffix;
        for(int role=0;role<2;role++)
        {
            Segment segment=default;if(record!=null)lock(record.Gate)segment=role==0?record.Hook:record.Run;
            var layout=(MirroredHookListenerLayout?)(role==0?Hook:Run).GetValue(__instance);
            if(segment.Layout is null||!ReferenceEquals(segment.Layout,layout)||segment.Offset+segment.Length!=layout!.Entries.Length)
            {Interlocked.Increment(ref Missing[role]);continue;}
            Interlocked.Increment(ref Found[role]);Interlocked.Add(ref Slots[role],suffix.Count);
            bool matches=segment.Length==suffix.Count;int compared=0;
            if(matches)for(int i=0;i<segment.Length;i++)
            {compared++;if(suffix[i] is null||suffix[i].GetType()!=layout.Entries[segment.Offset+i].Type){matches=false;break;}}
            Interlocked.Add(ref Compared[role],compared);
            if(matches){Interlocked.Increment(ref Match[role]);Interlocked.Add(ref MatchSlots[role],segment.Length);}
        }
    }
    private static void AfterFiltered(SimulatedCombatState __instance,bool run,IReadOnlyList<AbstractModel> __result,object? __state)
    {
        if(ReferenceEquals(__result,__state))return;
        var basis=(IReadOnlyList<AbstractModel>?)Base.GetValue(__instance);
        var source=(IReadOnlyList<AbstractModel>?)(run?WholeRun:Active).GetValue(__instance);
        var layout=(MirroredHookListenerLayout?)(run?Run:Hook).GetValue(__instance);
        if(basis is null||basis.GetType()!=Joined||basis is not ISegmentedModelList view||source is null||layout is null
            ||!Frozen(source)||!Frozen(view.Suffix)||!EndsWith(source,view.Suffix))return;
        int length=view.Suffix.Count,offset=source.Count-length;
        if(offset<0||source.Count!=layout.Entries.Length)throw new InvalidOperationException("Producer probe layout/source shape differs.");
        var record=Get(__instance);lock(record.Gate)
        {if(run)record.Run=new(layout,offset,length);else record.Hook=new(layout,offset,length);}
    }
    private static void AfterFork(SimulatedCombatState __instance,ICombatState __result)
    {
        if(__result is not SimulatedCombatState child||!Recorded.TryGetValue(__instance,out var parent))return;
        Segment hook,run;lock(parent.Gate){hook=parent.Hook;run=parent.Run;}
        var target=Get(child);lock(target.Gate){target.Hook=hook;target.Run=run;}
        Interlocked.Increment(ref _inherited);
    }
}

