    private static int ReadAeonglassCounter(
        Creature owner,
        IReadOnlyDictionary<Creature, int>? simulatedValues,
        string memberName)
    {
        if (simulatedValues != null && simulatedValues.TryGetValue(owner, out int value))
            return value;
