    private static void AddUnordered(
        ref StateFingerprintBuilder fingerprint,
        char marker,
        int count,
        ulong first,
        ulong second)
    {
        fingerprint.Add(marker);
        fingerprint.Add(count);
        fingerprint.Add(first);
        fingerprint.Add(second);
    }

