// Immutable type metadata, shared across forks. It never retains any combat models.
internal sealed class MirroredHookListenerLayout(
    MirroredHookListenerLayout.Entry[] entries,
    MirroredHookMask combined)
{
    internal readonly record struct Entry(Type Type, MirroredHookMask Mask);
    internal Entry[] Entries { get; } = entries;
    internal bool HasAny(MirroredHookMask mask) => (combined & mask) != 0;
    internal bool Matches(IReadOnlyList<AbstractModel> source, int verifiedSuffixLength = 0)
    {
        if (source.Count != Entries.Length || verifiedSuffixLength < 0 || verifiedSuffixLength > Entries.Length)
            return false;
        for (int index = 0; index < source.Count - verifiedSuffixLength; index++)
            if (source[index].GetType() != Entries[index].Type)
                return false;
        return true;
    }
}

// A producer checks concrete receiver types while building its own frozen suffix.
// The caller must retain that exact suffix identity in the consumed complete source.
// Neither this proof nor the builder retains receiver models or branch state.
internal readonly record struct MirroredHookListenerTypeProof(
    MirroredHookListenerLayout? Layout, int Length);

internal struct MirroredHookListenerTypeProofBuilder
{
    private MirroredHookListenerLayout? _layout;
    private readonly int _offset;
    private readonly int _length;
    private int _observed;

    internal MirroredHookListenerTypeProofBuilder(MirroredHookListenerLayout? layout, int length)
    {
        _layout = layout is not null && length >= 0 && length <= layout.Entries.Length ? layout : null;
        _length = length;
        _offset = _layout is null ? 0 : _layout.Entries.Length - length;
        _observed = 0;
    }

    internal bool NeedsType => _layout is not null;

    internal void Observe(Type? type)
    {
        if (_layout is null)
            return;
        if (_observed >= _length || type != _layout.Entries[_offset + _observed].Type)
        {
            _layout = null;
            return;
        }
        _observed++;
    }

    internal readonly MirroredHookListenerTypeProof Complete()
        => _layout is not null && _observed == _length ? new(_layout, _length) : default;
}

// The original complete listener sequence plus its type-only dispatch layout.
// Model identity and order come exclusively from the branch's native snapshot.
internal sealed class MirroredHookListenerSnapshot(
    IReadOnlyList<AbstractModel> source,
    MirroredHookListenerLayout layout) : IReadOnlyList<AbstractModel>
{
    internal MirroredHookListenerLayout Layout { get; } = layout;
