using System.Collections;
using System.Reflection;
using System.Runtime.CompilerServices;
using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using HarmonyLib;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Cards;
using MegaCrit.Sts2.Core.Models.Powers;

namespace CombatSolver;

internal static class ProducerFusionProof
{
    private static readonly Type State = typeof(SimulatedCombatState);
    private static readonly Type View = State.GetNestedType("ConcatenatedListenerView", BindingFlags.NonPublic)!;
    private static readonly ConstructorInfo JoinConstructor = View.GetConstructors(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic).Single();
    private static readonly MethodInfo Tail = State.GetMethod("HasListenerSuffix", BindingFlags.Static | BindingFlags.NonPublic)!;
    private static readonly MethodInfo Remap = State.GetMethod("RemapCachedModels", BindingFlags.Static | BindingFlags.NonPublic)!;
    private static readonly PropertyInfo CombatProof = View.GetProperty("CombatProof", BindingFlags.Instance | BindingFlags.NonPublic)!;
    private static FieldInfo Field(string name) => State.GetField(name, BindingFlags.Instance | BindingFlags.NonPublic)!;
    private static readonly FieldInfo Base = Field("_baseHookListeners"), CombatLength = Field("_mirroredHookSuffixLength"), RunLength = Field("_mirroredRunHookSuffixLength");
    private static readonly MethodInfo Invalidate = State.GetMethod("InvalidateCardAndOrbHookListeners", BindingFlags.Instance | BindingFlags.NonPublic)!;
    private static long _calls, _proofs, _slots;

    private static IReadOnlyList<AbstractModel> Join(IReadOnlyList<AbstractModel> prefix, IReadOnlyList<AbstractModel> suffix,
        MirroredHookListenerTypeProof combat = default, MirroredHookListenerTypeProof run = default)
        => (IReadOnlyList<AbstractModel>)JoinConstructor.Invoke([prefix, suffix, combat, run]);

    private static MirroredHookListenerTypeProof Prove(MirroredHookListenerLayout layout, int length, IEnumerable<AbstractModel?> values)
    {
        MirroredHookListenerTypeProofBuilder builder = new(layout, length);
        foreach (var value in values) builder.Observe(value?.GetType());
        return builder.Complete();
    }

    private static void BeforeFilter(IReadOnlyList<AbstractModel> source, MirroredHookListenerLayout? layout,
        MirroredHookListenerTypeProof suffixProof)
    {
        Interlocked.Increment(ref _calls);
        if (suffixProof.Layout is null || !ReferenceEquals(suffixProof.Layout, layout)) return;
        if (suffixProof.Length < 0 || suffixProof.Length > source.Count || layout!.Entries.Length != source.Count)
            throw new InvalidOperationException("Actual producer proof shape differs.");
        for (int i = source.Count - suffixProof.Length; i < source.Count; i++)
            if (source[i].GetType() != layout.Entries[i].Type)
                throw new InvalidOperationException("Actual producer proof receiver type/order differs.");
        Interlocked.Increment(ref _proofs); Interlocked.Add(ref _slots, suffixProof.Length);
    }

    internal static IDisposable VerifyAndObserve(CombatState live, CombatPredictionSimulator parent, Player player,
        Func<CombatPredictionSimulator, string> stamp, Action<string> record)
    {
        string parentBefore = stamp(parent), liveBefore = ContinuationStamp.CaptureLive(live).StateText;
        AbstractModel card = ModelDb.Card<StrikeIronclad>(), alternate = ModelDb.Card<DefendIronclad>(), power = ModelDb.Power<StrengthPower>();
        int cases = 0;
        foreach (int count in new[] { 0, 1, 8, 32 })
        {
            AbstractModel[] suffix = Enumerable.Range(0, count).Select(i => i % 2 == 0 ? card : alternate).ToArray();
            AbstractModel[] full = [power, .. suffix];
            MirroredHookListenerLayout? layout = null;
            var filter = new MirroredHookListenerFilter(true);
            _ = filter.Filter(full, ref layout);
            MirroredHookListenerTypeProof proof = Prove(layout!, count, suffix);
            if (!ReferenceEquals(proof.Layout, layout) || proof.Length != count)
                throw new InvalidOperationException("Known ordered suffix was rejected.");
            IReadOnlyList<AbstractModel>[] sources = [full, full.ToList(), Join([power], suffix), Join([], Join([power], suffix))];
            foreach (var source in sources)
            {
                MirroredHookListenerLayout? a = layout, b = layout;
                var expected = (MirroredHookListenerSnapshot)filter.Filter(source, ref a);
                var actual = (MirroredHookListenerSnapshot)filter.Filter(source, ref b, proof);
                if (!expected.SequenceEqual(actual, ReferenceEqualityComparer.Instance)
                    || !a!.Entries.SequenceEqual(b!.Entries))
                    throw new InvalidOperationException("Fused type match changed receivers/masks.");
                cases++;
            }
            AbstractModel[] prefixChanged = [alternate, .. suffix];
            MirroredHookListenerLayout? changed = layout;
            _ = filter.Filter(prefixChanged, ref changed, proof);
            if (!changed!.Matches(prefixChanged)) throw new InvalidOperationException("Verified suffix skipped the changed prefix.");
            foreach (int badLength in new[] { -1, layout!.Entries.Length + 1 })
                if (Prove(layout, badLength, suffix).Layout is not null)
                    throw new InvalidOperationException("Invalid descriptor length was certified.");
            if (count > 0)
            {
                AbstractModel?[] missing = suffix.Take(count - 1).ToArray();
                AbstractModel?[] changedType = [alternate, .. suffix.Skip(1)];
                AbstractModel?[] nullType = [null, .. suffix.Skip(1)];
                AbstractModel?[] extra = [.. suffix, card];
                foreach (var values in new[] { missing, changedType, nullType, extra })
                    if (Prove(layout!, count, values).Layout is not null)
                        throw new InvalidOperationException("Incomplete/changed/null/extra suffix was certified.");
            }
            var getter = new GetterList(suffix);
            if ((bool)Tail.Invoke(null, [getter, suffix])! || getter.CountReads != 0 || getter.IndexReads != 0)
                throw new InvalidOperationException("Unknown tail qualification read callbacks.");
            var external = new ExternalSegments([power], getter);
            if ((bool)Tail.Invoke(null, [external, suffix])! || getter.CountReads != 0 || getter.IndexReads != 0)
                throw new InvalidOperationException("External marker was trusted as a producer.");
            var view = Join([power], suffix, proof);
            using PredictionForkContext context = new();
            if (count > 0) context.Register<object>(card, power);
            var remapped = (IReadOnlyList<AbstractModel>)Remap.Invoke(null, [view, context])!;
            var resultProof = (MirroredHookListenerTypeProof)CombatProof.GetValue(remapped)!;
            if (count > 0 && resultProof.Layout is not null)
                throw new InvalidOperationException("Changed suffix retained its producer proof.");
        }

        Harmony harmony = new("CombatSolver.Tests.ListenerProducerFusion");
        MethodInfo filterMethod = typeof(MirroredHookListenerFilter).GetMethod("Filter", BindingFlags.Instance | BindingFlags.NonPublic,
            null, [typeof(IReadOnlyList<AbstractModel>), typeof(MirroredHookListenerLayout).MakeByRefType(), typeof(MirroredHookListenerTypeProof)], null)!;
        harmony.Patch(filterMethod, prefix: new HarmonyMethod(typeof(ProducerFusionProof).GetMethod(nameof(BeforeFilter), BindingFlags.Static | BindingFlags.NonPublic)!));
        try
        {
            using var isolation = SimulationNotificationIsolation.Enter();
            var seed = parent.Fork();
            var state = (SimulatedCombatState)seed.State.CombatState;
            state.Apply<StrengthPower>(player.Creature, 2, player.Creature);
            if (!CombatBeamSolver.SettleReplayActionBoundary(seed, state)) throw new InvalidOperationException("Unexpected Power boundary.");
            var source = (ICombatPredictionHookListenerSource)state;
            _ = source.MirroredHookListeners; _ = source.MirroredRunHookListeners;
            Invalidate.Invoke(state, null);
            _ = source.MirroredHookListeners; _ = source.MirroredRunHookListeners;
            var basis = (IReadOnlyList<AbstractModel>)Base.GetValue(state)!;
            if (((MirroredHookListenerTypeProof)CombatProof.GetValue(basis)!).Layout is null)
                throw new InvalidOperationException("Native producer did not certify a stable suffix.");
            string seedBefore = stamp(seed);
            Parallel.For(0, 16, i =>
            {
                using var workerIsolation = SimulationNotificationIsolation.Enter();
                CombatPredictionSimulator actual, expected;
                lock (seed) { actual = seed.Fork(); expected = seed.Fork(); }
                var a = (SimulatedCombatState)actual.State.CombatState;
                var b = (SimulatedCombatState)expected.State.CombatState;
                CombatLength.SetValue(b, -1); RunLength.SetValue(b, -1);
                actual.State.GetPlayerCombatState(player).Hand.Cards[0].MutablePreview.BaseReplayCount = i + 1;
                expected.State.GetPlayerCombatState(player).Hand.Cards[0].MutablePreview.BaseReplayCount = i + 1;
                Invalidate.Invoke(a, null); Invalidate.Invoke(b, null);
                var sa = (ICombatPredictionHookListenerSource)a; var sb = (ICombatPredictionHookListenerSource)b;
                var ac = sa.MirroredHookListeners; var bc = sb.MirroredHookListeners;
                var ar = sa.MirroredRunHookListeners; var br = sb.MirroredRunHookListeners;
                if (!ac.Select(m => m.GetType()).SequenceEqual(bc.Select(m => m.GetType()))
                    || !ar.Select(m => m.GetType()).SequenceEqual(br.Select(m => m.GetType()))
                    || stamp(actual) != stamp(expected))
                    throw new InvalidOperationException("Native fused/reference state/history/RNG differs.");
                if (ReferenceEquals(a.GetPower<StrengthPower>(player.Creature), state.GetPower<StrengthPower>(player.Creature)))
                    throw new InvalidOperationException("Fork retained parent Power receiver.");
                if (stamp(actual.Fork()) != stamp(actual)) throw new InvalidOperationException("Second-generation Fork differs.");
            });
            if (stamp(seed) != seedBefore || stamp(parent) != parentBefore || ContinuationStamp.CaptureLive(live).StateText != liveBefore)
                throw new InvalidOperationException("Producer proof changed parent/live state.");
            record($"ListenerProducerFusion:Cases={cases}:PrefixCountNullChangedIncompleteUnknownMarkerRemap:Native16ForksTwoGenerations:FullStateHistoryRngParentLive");
        }
        catch { harmony.UnpatchAll(harmony.Id); throw; }
        return new Observation(harmony, record);
    }

    private sealed class Observation(Harmony harmony, Action<string> record) : IDisposable
    {
        public void Dispose()
        {
            harmony.UnpatchAll(harmony.Id);
            if (_proofs == 0 || _slots == 0) throw new InvalidOperationException("No actual producer proof consumption.");
            record($"ListenerProducerFusion:ActualFilterCalls={_calls}:Proofs={_proofs}:VerifiedSlots={_slots}");
        }
    }
    private sealed class GetterList(AbstractModel[] values) : IReadOnlyList<AbstractModel>
    {
        internal int CountReads, IndexReads;
        public int Count { get { CountReads++; return values.Length; } }
        public AbstractModel this[int index] { get { IndexReads++; return values[index]; } }
        public IEnumerator<AbstractModel> GetEnumerator() => ((IEnumerable<AbstractModel>)values).GetEnumerator();
        IEnumerator IEnumerable.GetEnumerator() => GetEnumerator();
    }
    private sealed class ExternalSegments(IReadOnlyList<AbstractModel> prefix, IReadOnlyList<AbstractModel> suffix) : IReadOnlyList<AbstractModel>, ISegmentedModelList
    {
        public IReadOnlyList<AbstractModel> Prefix => prefix;
        public IReadOnlyList<AbstractModel> Suffix => suffix;
        public int Count => prefix.Count + suffix.Count;
        public AbstractModel this[int index] => index < prefix.Count ? prefix[index] : suffix[index - prefix.Count];
        public IEnumerator<AbstractModel> GetEnumerator() => prefix.Concat(suffix).GetEnumerator();
        IEnumerator IEnumerable.GetEnumerator() => GetEnumerator();
    }
}

